return [{ json: { pages: [
  { name: 'Landing Page', url: 'https://dev.nerja.ai/', expectedStatus: 200, expectedTitle: 'Nerja AI' },
  { name: 'Login Page', url: 'https://dev.nerja.ai/login', expectedStatus: 200, expectedTitle: 'Log in' },
  { name: 'Signup Page', url: 'https://dev.nerja.ai/signup', expectedStatus: 200, expectedTitle: 'Sign up' },
  { name: 'Forgot Password', url: 'https://dev.nerja.ai/forgot-password', expectedStatus: 200, expectedTitle: 'Nerja' },
  { name: 'Pricing Page', url: 'https://dev.nerja.ai/pricing', expectedStatus: 200, expectedTitle: 'Nerja' }
] } }];

const r = $json;
const page = $('Split Pages').item.json;
const statusOk = r.statusCode === page.expectedStatus;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const titleOk = body.includes(page.expectedTitle);
const ok = statusOk && titleOk;
return [{ json: { name: page.name, url: page.url, statusCode: r.statusCode, passed: ok, detail: ok ? '✅ ' + page.name + ' → ' + r.statusCode : '❌ ' + page.name + ' → ' + r.statusCode + (statusOk ? '' : ' (expected ' + page.expectedStatus + ')') + (!titleOk ? ' [title mismatch]' : '') } }];

const results = $json.results || [];
const passed = results.filter(r => r.passed).length;
const failed = results.filter(r => !r.passed).length;
console.log('\n╔══════════════════════════════════════╗');
console.log('║  NERJA AI — PUBLIC PAGES RESULTS     ║');
console.log('╚══════════════════════════════════════╝');
results.forEach(r => console.log(r.detail));
console.log('\n→ ' + passed + '/' + results.length + ' passed | ' + failed + ' failed');
return [{ json: { suite: '02 Public Pages', total: results.length, passed, failed, status: failed === 0 ? 'PASS' : 'FAIL', tests: results, timestamp: new Date().toISOString() } }];
